-- QEPEX India Work Tracker — fresh v5 demo data generated for 2026-10-06 (what "Reset demo data" creates). Fictional.

PRAGMA foreign_keys = OFF;

CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS users (
  "id" TEXT NOT NULL,
  "employee_code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "designation" TEXT NOT NULL,
  "is_senior" INTEGER,
  "email" TEXT,
  "phone" TEXT,
  "default_location" TEXT NOT NULL,
  "location_override_allowed" INTEGER NOT NULL,
  "joining_date" TEXT NOT NULL,
  "principal_partner_id" TEXT REFERENCES users,
  "active" INTEGER NOT NULL,
  "deactivated_on" TEXT,
  "deactivated_by" TEXT REFERENCES users,
  "deactivation_note" TEXT,
  extra_json TEXT,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS ix_users_principal_partner_id ON users("principal_partner_id");

CREATE INDEX IF NOT EXISTS ix_users_deactivated_by ON users("deactivated_by");

CREATE TABLE IF NOT EXISTS user_auth (
  "user_id" TEXT NOT NULL,
  "credential_kind" TEXT NOT NULL,
  "password_hash" TEXT,
  "password_salt" TEXT,
  "hash_iterations" INTEGER NOT NULL,
  "must_change_password" INTEGER NOT NULL,
  "temp_pin_issued_at" TEXT,
  "temp_pin_issued_by" TEXT REFERENCES users,
  "failed_attempts" INTEGER NOT NULL,
  "locked_until" TEXT,
  "last_login_at" TEXT,
  "totp_secret" TEXT,
  "totp_enrolled_at" TEXT,
  extra_json TEXT,
  PRIMARY KEY ("user_id")
);

CREATE INDEX IF NOT EXISTS ix_user_auth_temp_pin_issued_by ON user_auth("temp_pin_issued_by");

CREATE TABLE IF NOT EXISTS clients (
  "id" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "group" TEXT,
  "constitution" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "status_effective_from" TEXT,
  "pan" TEXT,
  "tan" TEXT,
  "cin" TEXT,
  "udyam" TEXT,
  "state_code" TEXT,
  "fy_end" TEXT NOT NULL,
  "agm_date" TEXT,
  "auditor_appointment_date" TEXT,
  "books_by" TEXT NOT NULL,
  "partner_id" TEXT NOT NULL REFERENCES users,
  "manager_id" TEXT REFERENCES users,
  "contact_name" TEXT,
  "contact_phone" TEXT,
  "contact_email" TEXT,
  "profile" TEXT NOT NULL,
  "compliance_start_dates" TEXT NOT NULL,
  "flag_history" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "updated_by" TEXT NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS ix_clients_partner_id ON clients("partner_id");

CREATE INDEX IF NOT EXISTS ix_clients_manager_id ON clients("manager_id");

CREATE TABLE IF NOT EXISTS client_gstins (
  client_id TEXT NOT NULL REFERENCES clients,
  position INTEGER NOT NULL,
  "id" TEXT NOT NULL,
  "gstin" TEXT NOT NULL,
  "state_code" TEXT NOT NULL,
  "state" TEXT NOT NULL,
  "frequency" TEXT NOT NULL,
  "effective_from" TEXT NOT NULL,
  "frequency_history" TEXT NOT NULL,
  "gst_annual_return" INTEGER NOT NULL,
  "gst9c" INTEGER NOT NULL,
  "iff_opted" INTEGER NOT NULL,
  "status" TEXT NOT NULL,
  "cancelled_on" TEXT,
  extra_json TEXT,
  PRIMARY KEY (client_id, id)
);

CREATE INDEX IF NOT EXISTS ix_client_gstins_client_id ON client_gstins(client_id, position);

CREATE TABLE IF NOT EXISTS client_directors (
  client_id TEXT NOT NULL REFERENCES clients,
  position INTEGER NOT NULL,
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "din" TEXT NOT NULL,
  "designation" TEXT NOT NULL,
  "dsc_id" TEXT,
  "appointed_on" TEXT,
  "ceased_on" TEXT,
  "active" INTEGER NOT NULL,
  extra_json TEXT,
  PRIMARY KEY (client_id, id)
);

CREATE INDEX IF NOT EXISTS ix_client_directors_client_id ON client_directors(client_id, position);

CREATE TABLE IF NOT EXISTS client_team (
  "client_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("client_id", "user_id")
);

CREATE TABLE IF NOT EXISTS compliance_types (
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "short_name" TEXT NOT NULL,
  "service_line" TEXT NOT NULL,
  "engagement_group" TEXT NOT NULL,
  "template_code" TEXT NOT NULL REFERENCES stage_templates,
  "frequency" TEXT NOT NULL,
  "rule" TEXT NOT NULL,
  "due_variants" TEXT,
  "applicability" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "period_label_style" TEXT,
  "default_budget_hours" REAL NOT NULL,
  "is_active" INTEGER NOT NULL,
  "is_custom" INTEGER,
  "retired" INTEGER,
  "replaced_by" TEXT,
  "illustrative" INTEGER NOT NULL,
  "verified_by" TEXT,
  "verified_at" TEXT,
  extra_json TEXT,
  PRIMARY KEY ("code")
);

CREATE INDEX IF NOT EXISTS ix_compliance_types_template_code ON compliance_types("template_code");

CREATE TABLE IF NOT EXISTS stage_templates (
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "family" TEXT,
  "stages" TEXT NOT NULL,
  "filing_stage_index" INTEGER,
  "ack_type" TEXT,
  "review_level" TEXT NOT NULL,
  "checklist" TEXT NOT NULL,
  "requires_signoff" INTEGER NOT NULL,
  "requires_udin" INTEGER NOT NULL,
  "version" INTEGER NOT NULL,
  "versions" TEXT NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("code")
);

CREATE TABLE IF NOT EXISTS engagements (
  "id" TEXT NOT NULL,
  "client_id" TEXT NOT NULL REFERENCES clients,
  "service_line" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "financial_year" TEXT,
  "template_code" TEXT NOT NULL REFERENCES stage_templates,
  "status" TEXT NOT NULL,
  "partner_id" TEXT NOT NULL REFERENCES users,
  "manager_id" TEXT REFERENCES users,
  "team" TEXT NOT NULL,
  "budget_hours" REAL,
  "billable" INTEGER NOT NULL,
  "fee_basis" TEXT,
  "start_date" TEXT,
  "end_date" TEXT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS ix_engagements_client_id ON engagements("client_id");

CREATE INDEX IF NOT EXISTS ix_engagements_template_code ON engagements("template_code");

CREATE INDEX IF NOT EXISTS ix_engagements_partner_id ON engagements("partner_id");

CREATE INDEX IF NOT EXISTS ix_engagements_manager_id ON engagements("manager_id");

CREATE TABLE IF NOT EXISTS tasks (
  "id" TEXT NOT NULL,
  "client_id" TEXT NOT NULL REFERENCES clients,
  "engagement_id" TEXT NOT NULL REFERENCES engagements,
  "kind" TEXT NOT NULL,
  "compliance_type_code" TEXT REFERENCES compliance_types,
  "period_key" TEXT,
  "period_label" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "template_code" TEXT NOT NULL REFERENCES stage_templates,
  "template_version" INTEGER NOT NULL,
  "gstin_id" TEXT REFERENCES client_gstins,
  "director_id" TEXT REFERENCES client_directors,
  "original_due" TEXT NOT NULL,
  "effective_due" TEXT NOT NULL,
  "provisional" INTEGER,
  "status" TEXT NOT NULL,
  "stage_index" INTEGER NOT NULL,
  "pending_periods" TEXT NOT NULL,
  "ack" TEXT,
  "signoff" TEXT,
  "review" TEXT,
  "na_reason" TEXT,
  "superseded_by_task_id" TEXT REFERENCES tasks,
  "assigned_to" TEXT REFERENCES users,
  "checker_id" TEXT REFERENCES users,
  "budget_hours" REAL,
  "status_history" TEXT NOT NULL,
  "due_history" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "updated_by" TEXT NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS ix_tasks_client_id ON tasks("client_id");

CREATE INDEX IF NOT EXISTS ix_tasks_engagement_id ON tasks("engagement_id");

CREATE INDEX IF NOT EXISTS ix_tasks_compliance_type_code ON tasks("compliance_type_code");

CREATE INDEX IF NOT EXISTS ix_tasks_template_code ON tasks("template_code");

CREATE INDEX IF NOT EXISTS ix_tasks_gstin_id ON tasks("gstin_id");

CREATE INDEX IF NOT EXISTS ix_tasks_director_id ON tasks("director_id");

CREATE INDEX IF NOT EXISTS ix_tasks_superseded_by_task_id ON tasks("superseded_by_task_id");

CREATE INDEX IF NOT EXISTS ix_tasks_assigned_to ON tasks("assigned_to");

CREATE INDEX IF NOT EXISTS ix_tasks_checker_id ON tasks("checker_id");

CREATE TABLE IF NOT EXISTS task_review_points (
