  "reason" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "supersedes_id" TEXT REFERENCES extensions,
  "published_at" TEXT NOT NULL,
  "published_by" TEXT NOT NULL,
  "tasks_moved" INTEGER NOT NULL,
  extra_json TEXT,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS ix_extensions_compliance_type_code ON extensions("compliance_type_code");

CREATE INDEX IF NOT EXISTS ix_extensions_supersedes_id ON extensions("supersedes_id");

