  "status" TEXT NOT NULL,
  "applied_at" TEXT NOT NULL,
  "decided_by" TEXT REFERENCES users,
  "decided_at" TEXT,
  "decision_note" TEXT,
  "conflict_task_ids" TEXT NOT NULL,
