CREATE TABLE IF NOT EXISTS udin_register (
  "id" TEXT NOT NULL,
  "client_id" TEXT NOT NULL REFERENCES clients,
  "task_id" TEXT REFERENCES tasks,
  "engagement_id" TEXT REFERENCES engagements,
